  _ = `输入关键字，以筛选您的程序包列表。`,
  _ = `注意：这些并非 AppID，而是在 Steam 商店中用于销售您产品的商店程序包。`,
  _ = `在此处输入程序包名称或 ID`,
  _ = `在下方选择一个或多个程序包并点击“继续”，将其添加到此捆绑包中。`,
  _ = `捆绑包协作`,
  _ = `可选：您可以选择邀请其他开发者将其游戏纳入您的捆绑包中。您作为捆绑包的所有者，有责任与其他开发者协调，而且，也只有您可以在 Steam 商店中发布捆绑包。受邀参与方可以选择要纳入哪些游戏或捆绑包。每次将程序包添加至捆绑包中或折扣百分比发生变化时，所有的协作方必须批准将其游戏纳入捆绑包中，才能发布。`,
