  _ = `特卖推广活动页面`,
  _ = `如果 Steam 上一些特卖页面包含您拥有管理权限的一款或多款游戏，这些页面就可在此处找到。 在某些情况下，这些页面由活动组织者安排整理，有时作为筹备好的促销活动的一部分，也会由 Valve 安排整理。`,
  _ = `这些是所有进行中及已安排的特卖页面，由 Valve 或被批准的外部参与方创建。要设置允许新的合作伙伴创建自己的特卖页面，%1$s。您可以向自己的合作伙伴转发%2$s。`,
