  _ = `创建新的特卖活动`,
  _ = `选择一个合适的社区组以在其中创建活动和特卖`,
  _ = `输入组名称或商店 URL`,
  _ = `特卖活动需要在创作者主页（又名开发者/发行商/系列作品页面）上创建。在下方搜索创作者主页名称：`,
  _ = `输入与创作者主页关联的组名称，如果是鉴赏家或新创建的社区组，则输入商店 URL。`,
  _ = `1. 已选择举办特卖活动的创作者：`,
