  _ = `此创作者主页需要加入合作伙伴活动测试才能使用特卖功能。此操作无法撤销。此举将更改他们发布公告的编辑器，并阻止其创建带链接的公告。%1$s`,
  _ = `3. 输入所需的最少信息：`,
  _ = `描述性活动名称`,
