  _ = `创建活动！`,
  _ = `创建活动失败。查看浏览器控制台以了解详情。`,
  _ = `特卖活动已成功创建。点击下方在编辑模式中打开活动。您也可以提供 URL 给合作伙伴进行编辑。`,
  _ = `已选择的%1$s总数：已选择 %2$s 款应用和 %3$s 个程序包。`,
  _ = `Valve Corporation`,
  _ = `关于讲者`,
  _ = `Gautam Babbar - Valve 设计师`,
  _ = `过去 15 年里，Gautam 参与制作了 Valve 的多个系列作品与产品，包括《求生之路》、《传送门》、《半衰期》、《反恐精英》、《异星虫群》和 Steam。目前他正为 CS:GO 的开发制作而效力。`,
  _ = `Adil Sardar - Valve 工程师`,
  _ = `Adil 是 Steam 软件开发团队的一员，参与创建了 Steam 技术堆栈上的各项功能，最近正致力于各个活动、特卖和实况直播方面的技术支持工作。`,
  _ = `Alden Kroll - Valve 设计师`,
  _ = `Valve 的设计师 Alden Kroll 在 Valve 从事设计工作已超过 15 年，参与了 Steam 以及《军团要塞 2》、《传送门》和《求生之路》的开发。Alden 目前作为 Steam 商店和 Steamworks 发布工具的设计师，从事设计、商务及外联等多项工作，同时还帮助组织与开发者接触沟通的活动。`,
  _ = `Jenny Windom - Rose City Games 外联经理`,
  _ = `Jenny 热衷于独立游戏及其社区，并积极倡导行业各个层面上的人群多样化。她不仅担任 Rose City Games（作品包括 The World Next Door、Floppy Knights、Garden Story）的外联经理，也在 Kowloon Nights 从事外联工作，同时还是自由的独立游戏策划人和内容创造者！`,
  _ = `Joe Tirado - System Era Softworks 的外联与营销团队负责人`,
  _ = `Joe 是一名艺术家、设计师，也是多元化倡导者。Joe 在 System Era Softworks 供职时，是游戏 Astroneer 开发团队的一员，该游戏在 2019 年的 Webby Awards 上斩获“Best Adventure Game”（最佳冒险游戏），并在 SXSW Gaming Awards 上夺得“Gamer’s Voice Award”（玩家之声奖）。Joe 还是在游戏行业聚合并代表拉丁裔工作者的平台 Latinx in Gaming 的联合创始人。`,
  _ = `Steam 沟通工具实际演示`,
  _ = `Alden Kroll 及 Adil Sardar - Valve Corporation`,
  _ = `上午 11:00 - 下午 12:02（PT）`,
  _ = `Steam 活动和公告的几位创建者会在此会议中为您一步步演示如何使用这一功能。学习基本要点、查看工具实际应用情况并了解最佳实践，以将 Steam 沟通工具物尽其用。`,
  _ = `让更新说明一切`,
  _ = `Gautam Babbar - Valve Corporation`,
  _ = `上午 10:20 - 10:47（PT）`,
  _ = `《反恐精英：全球攻势》有着庞大的全球玩家社区。在此演讲中，Gautam 会详细描述 CS:GO 团队如何利用内容和游戏变更来和如此广大的受众进行沟通。他也会就游戏团队斟酌该何时发声、何时倾听这一问题提出自己的看法。`,
  _ = `和玩家沟通：第 1 部分`,
  _ = `Jenny Windom - Rose City Games`,
  _ = `下午 12:15 - 12:55（PT）`,
  _ = `有些时候，大家可能觉得玩家沟通和活动仅对大型多人在线游戏有用，不过在此谈话中，Jenny 向我们力证事实并非如此。此会议着重讨论围绕两款较小型的单人游戏创建社区和进行互动的策略和技巧。这两款游戏为：由 Picogram 开发且即将推出的冒险角色扮演游戏 Garden Sotry，以及由 Rose City Games 开发的卡牌战斗游戏 Floppy Knights。`,
  _ = `和玩家沟通：第 2 部分`,
  _ = `Joe Tirado - System Era Softworks`,
  _ = `下午 1:00 - 1:44（PT）`,
  _ = `Astroneer 于 2016 年年底通过 Steam 抢先体验首次登台亮相。近五年后，这款游戏仍持续在新老玩家间产生共鸣。Joe 分享了他的经验，讲述小型团队可以如何利用沟通来在开发早期促进玩家参与，以及如何在游戏的整个生命周期中处理反馈意见。`,
  _ = `必需`,
