  _ = `为游戏加入活动进行申诉`,
  _ = `游戏没有资格参加此活动`,
  _ = `受邀参加官方 Steam 主题特卖或新品节的游戏必须符合活动的具体主题和参加资格标准，如上所述。对于主题特卖，游戏必须通过以下两个重要的测试：`,
  _ = `对于新品节，参加资格取决于 Steamworks 中设置的游戏发行日期。`,
  _ = `如果你认为自己的游戏完全符合上述资格标准，可以在此处开启申诉流程让我们知晓，并描述我们在审核游戏时可能漏掉的内容。`,
