  _ = `（参加必填）`,
  _ = `（建议，用于组织我们的活动）`,
  _ = `您的游戏目前被安排出现在下列栏目中。您游戏所在的选项卡由您在下方选择的“游戏分类”决定，而所在栏目则由您游戏所应用的商店标签决定。请查看活动预览，了解也许最适合您游戏的栏目。（例如，如果您有一款指向点击式冒险游戏，您最好确保在下方选择了“冒险”类别，并确保您游戏的商店页面标签包含“指向点击”。）请注意，这可能会在做出最后的栏目安排变更时随之改变。`,
  _ = `活动注册`,
