  _ = `资产包`,
  _ = `我们准备了一份资产包，帮助各位对自己的玩家及更广泛的游戏社区进行宣传。资产包现已可用，也可以在活动期间使用。%1$s`,
  _ = `查看资产包`,
  _ = `媒体预玩`,
  _ = `我们给您提供了在活动前与媒体互相联系的机会。如果您希望提前将自己的试用版提供给媒体，请于 %2$s 前在%1$s的“媒体预玩”一栏中表明参加意愿。`,
  _ = `注册表格`,
  _ = `安排现场直播`,
  _ = `您可以在 %2$s期间安排至多 %1$s 场实况直播，以借此机会现场展示自己的游戏并与玩家畅聊。您还可以查看%3$s，了解其他实况直播的最新时间表，以便给自己的直播安排最合理的时间。`,
  _ = `预览页面`,
