  _ = `如果需要选择退出，请于 %1$s（PT）前取消注册，这样游戏仍具备参加未来版本的资格。下一个版本将于 %2$s（PT）举行。`,
  _ = `查看您游戏的分类`,
  _ = `此活动的%1$s现已推出。只有具有已注册参加该活动的一款或多款游戏的管理权限的 Steam 帐户可以访问此预览。`,
  _ = `开发者预览页面`,
  _ = `活动页面将利用标签把每款游戏正确分类至恰当的类型、子类型、主题及其他类别中。`,
