  _ = `需要两种格式：大型格式和手机版格式。对于此处的预览，即使您也创建了置顶展示的动态版本，也只需上其传静态版本。`,
  _ = `请将文件大小保持在 5MB 以下，类型为 .jpg、.gif、.png`,
  _ = `如果其主色调与 Steam 商店标准的蓝色反差太强烈，则可使用羽化边缘，也可以过渡到一个不同的纯色。`,
  _ = `关键内容应放置在图片中央的 940px 区域内。`,
  _ = `置顶展示支持动画，但不应该太花哨。如果您希望使用动画，请务必查阅上方链接的文档，遵守我们的动画规范。`,
  _ = `页中展示横幅资产（%1$s）`,
  _ = `用途：艺术作品会在首页和/或商店中心特别优惠栏目下方显示。`,
  _ = `需要两种格式：大型格式和手机版格式。请确保其中包含了明确的行动号召部分及活动日期。`,
  _ = `请将文件大小保持在 5MB 以下，类型为 .jpg、.gif、.png`,
  _ = `特卖页面资产（%1$s）`,
  _ = `在特卖页面中，有多种资产类型可供考虑。`,
  _ = `特卖背景图片`,
  _ = `用途：此艺术作品将在特卖页面的背景中显示。`,
  _ = `设计：左/右/底部边缘应渐变或过渡为单一纯色，且该颜色将应用于页面的其余部分。请仔细查看模板以了解详情。如果您不使用特卖页面徽标，那么这张图片应在其顶部的安全区域内包含您的活动徽标和日期。`,
  _ = `此图片应为静态图片，小于 5MB，.jpg 或 .png 格式`,
  _ = `特卖页面徽标`,
  _ = `用途：此图片在特卖页面顶部、背景图片前方显示。`,
  _ = `设计：此图片应在透明背景上包含您活动的徽标和日期。`,
  _ = `活动封面/预览`,
  _ = `用途：此艺术作品用于在 Steam 新闻中心及特别优惠页面上代表您的活动，会在玩家于社交媒体上分享您活动的 URL 时以预览形式显示。`,
  _ = `设计：此图片应包含您活动的徽标和日期。`,
  _ = `活动形象图`,
  _ = `用途：此艺术作品会显示在和您特卖页面关联的公告的顶部。`,
  _ = `设计：此图片并非至关重要，只是为了给您的书面公告添加一些背景和色彩。`,
  _ = `此图片应为静态图片，小于 5MB，.jpg 或 .png 格式`,
  _ = `商店页面横幅`,
  _ = `用途：此横幅将在您活动所包括的所有游戏顶部显示。因此，您需要从活动所包括的所有游戏的创作者处获得许可，否则不能使用此功能。`,
  _ = `设计：此图片应包含您活动的徽标和日期；理想情况下，还应包含活动的行动号召或简短标语，以便玩家了解背景情况。`,
  _ = `此图片应为静态图片，小于 5MB，.jpg 或 .png 格式`,
  _ = `商店页面横幅手机版`,
  _ = `用途：这是商店页面横幅的手机版。会在 500px 或更窄的屏幕上代替默认的商店页面横幅。`,
  _ = `此图片应该与您的默认商店页面横幅的内容非常接近。`,
  _ = `此图片应为静态图片，小于 5MB，.jpg 或 .png 格式`,
  _ = `提交资产`,
  _ = `提交资产…`,
  _ = `您的资产已提交至 Valve，您的工作已完成！提交的资产将自动显示在 Steam 团队的主面板上，供团队审核并为促销做准备。`,
  _ = `资产已提交！`,
  _ = `资产已提交！无需进一步执行资产相关操作。`,
  _ = `单击下方按钮将您的促销资产提交给 Valve。提交后，Steam 团队将开始审查，并为精选内容准备材料。`,
  _ = `无法提交，上述 URL 格式不正确。`,
  _ = `请填写必填字段，以提交资产请求。`,
  _ = `优惠截止时间：%1$s`,
  _ = `重要！资产要求`,
  _ = `请查看下面的核对清单并向我们发送所需的资产，以便我们将这一优惠翻译成 Steam 支持的所有语言！`,
  _ = `每个资产必须小于 5MB`,
  _ = `艺术作品必须包含在分层 Photoshop 文件（PSD）中`,
  _ = `请尽可能提供高分辨率的主要游戏/角色艺术作品（最好为智能对象）。这样做可以让我们在必要时重新使用这些资产来创建其他 Steam 宣传艺术作品。`,
  _ = `请将徽标（最好为智能对象）和艺术作品分开。`,
  _ = `所有文本都应可在 PSD 文档内的单独的“text”（文本）文件夹中进行编辑，以便我们的团队可以轻松地将其本地化。`,
  _ = `包含所有所使用的字体（尤其是自定义字体）。`,
  _ = `请将所有文本样式和图层保留在 Photoshop 中。请勿链接来自其他程序（如 Illustrator）的文件。`,
  _ = `如果是动画资产，还请提供不含文本和徽标的无缝循环 MP4 或 PNG 序列。请确保所有文本均位于单独的图层，且不应为动画，这样我们的团队才可以轻松地将其本地化。`,
  _ = `有关更多详情和示例，以及动画资产的详细信息，请参见<1>商店促销图像资产</1>。`,
