  _ = `最早可发行日期：您游戏的生成版本审核完成后。`,
  _ = `最早可发行日期：%1$s`,
  _ = `您的最早可发行日期为您商店页面公开显示为“即将推出”两周后或首次购买应用额度 21 天后，以较晚者为准。请相应地进行计划。`,
  _ = `您的最早可发行日期为您商店页面公开显示为“即将推出”两周后。请相应地进行计划。`,
  _ = `请设置您计划在 Steam 上发行应用程序的日期。如果还有很长时间才会发行，作出最可能的预测即可。如果您需要推迟发行，则必须在前一次指定的日期前至少两周于此处更新该日期。`,
  _ = `发行不可在周末进行，因为 Valve 无法帮助解决任何发行问题。`,
  _ = `所有时间均为美国太平洋时间。`,
  _ = `您的计划发行日期目前设为“%1$s”。如果您需要更改此日期，请在此处<1>联系 Valve</1>，说明您选择新发布日期的原因以及您希望设置的日期。您应当相当确定您会在新日期发行自己的应用。`,
