  _ = `查看愿望单文档`,
  _ = `您首次发行试用版时，可以选择让 Steam 通知所有将您的完整游戏加入愿望单的人。此选项在您试用版发行后的前两周内可用，且仅限一次。愿望单通知不能在发送另一份通知后的两周内再次发送，因此如果您计划在两周内发行游戏，最好不要发送试用版愿望单电子邮件。`,
  _ = `您的基础游戏设置为于两周内在 %1$s发行。如果您现在发送愿望单，添加了愿望单的用户将不会在完整发行时收到电子邮件！`,
