  _ = `<1><2>关于试用版发行仅可发送一次电子邮件。</2>即使您将来禁用并重新启用您的试用版，也只能发送一次愿望单通知电子邮件。</1> <1><2>Steam 不会在两周内向同一玩家发送超过一次电子邮件。</2>如果您在发送此电子邮件后的两周内发行完整游戏，则 Steam 将不会向现在发送电子邮件的任何人再发送游戏本身的发行通知电子邮件。请相应地制定计划。</1>`,
