  _ = `申请游戏测试序列号`,
  _ = `使用此表格为您的游戏测试程序包申请 Steam 序列号。所有 Steam 序列号的申请将由 Valve 视具体情况进行审核，通常在 48-72 小时内进行。`,
  _ = `也请使用下面的方框告诉我们关于这些序列号预期用途的更多信息，以便我们可以帮助确保您申请的数量符合需求。`,
